package com.gerenciadorrural.modules.herd.application;
import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class TenantMovementLog {private final TenantTransactionExecutor tx;private final PaddockRepository paddocks;private final MovementOperationRepository movements;public TenantMovementLog(TenantTransactionExecutor tx,PaddockRepository paddocks,MovementOperationRepository movements){this.tx=tx;this.paddocks=paddocks;this.movements=movements;}public Result execute(TenantContext c,UUID id,int page,int size){if(page<0||size<1||size>100)throw new HerdAnimalCommandInvalidException();return tx.execute(c,()->{paddocks.find(c.tenantId(),c.farmId(),id).orElseThrow(HerdPaddockNotFoundException::new);long total=movements.countMovements(c.tenantId(),c.farmId(),id);return new Result(movements.movements(c.tenantId(),c.farmId(),id,size,(long)page*size),page,size,total);});}public record Result(List<PaddockMovement> items,int page,int size,long totalElements){public int totalPages(){return totalElements==0?0:(int)((totalElements+size-1)/size);}}}
